t.script:
(function(){
  "use strict";
  function $(s,r){return (r||document).querySelector(s);}
  function qa(s,r){return Array.from((r||document).querySelectorAll(s));}
  function $val(id,d){var el=$("#"+id);return el?el.value:d;}

  function loadImage(src){return new Promise(function(res,rej){var i=new Image();i.onload=function(){res(i)};i.onerror=rej;i.src=src;});}
  function readAsDataURL(f){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){res(r.result)};r.onerror=rej;r.readAsDataURL(f);});}

  function applyTransform(){
    var logo=$("#spw_logo_preview"); if(!logo) return;
    var base=$("#spw_product_img");  if(!base) return;
    var sizePx=+($val("spw_size","100")||100);
    var posX=+($val("spw_pos_x","0")||0);
    var posY=+($val("spw_pos_y","10")||10);
    var rot =+($val("spw_rotation","0")||0);

    var bw=base.clientWidth, bh=base.clientHeight;
    var leftPx=bw*(0.5 + posX/100);
    var topPx =bh*(0.6 + posY/100);

    logo.style.position="absolute";
    logo.style.left=leftPx+"px";
    logo.style.top =topPx+"px";
    logo.style.transform="translate(-50%,-50%) rotate("+rot+"deg)";
    logo.style.width=sizePx+"px";
    logo.classList.remove("d-none");
    logo.style.opacity="1";
  }

  async function renderPNGDataURL(){
    var internal=$("#spw-base-img");
    var baseSrc=(internal && internal.getAttribute("src")) ||
                $val("spw_img_src","") ||
                ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin imagen base.");
    var baseIm=await loadImage(baseSrc);

    var c=document.createElement("canvas"), ctx=c.getContext("2d");
    c.width=baseIm.naturalWidth||baseIm.width;
    c.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,c.width,c.height);

    var logo=$("#spw_logo_preview");
    if(logo && logo.src){
      var baseEl=$("#spw_product_img");
      var bw=baseEl.clientWidth, bh=baseEl.clientHeight;
      var br=baseEl.getBoundingClientRect();
      var lr=logo.getBoundingClientRect();

      var cx=((lr.left+lr.width/2)-br.left)/bw * c.width;
      var cy=((lr.top +lr.height/2)-br.top )/bh * c.height;
      var drawW=(lr.width/bw)*c.width;

      var lim=new Image(); await new Promise((ok,ko)=>{lim.onload=ok;lim.onerror=ko;lim.src=logo.src;});
      var ratio=(lim.naturalHeight||lim.height)/(lim.naturalWidth||lim.width);
      var drawH=drawW*ratio;
      var rot=(+($val("spw_rotation","0")||0) * Math.PI)/180;

      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot);
      ctx.drawImage(lim,-drawW/2,-drawH/2,drawW,drawH);
      ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  async function postJSON(url,p){try{var r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(p)});var t=await r.text();var d=null;try{d=JSON.parse(t)}catch(_){ }return{ok:!!(d&&(d.ok===true||d.ok==="true")),data:d,status:r.status,raw:t};}catch(e){return{ok:false,data:null,status:0,raw:String(e)}}}
  async function postForm(url,p){try{var fd=new FormData();Object.keys(p||{}).forEach(k=>fd.append(k,p[k]));var r=await fetch(url,{method:"POST",body:fd,credentials:"same-origin"});var t=await r.text();var d=null;try{d=JSON.parse(t)}catch(_){ }return{ok:r.ok && (!!d?(d.ok===true||d.ok==="true"):true),data:d||{},status:r.status,raw:t};}catch(e){return{ok:false,data:null,status:0,raw:String(e)}}}

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim();
    var qty=parseInt($val("spw_qty","1"),10)||1;
    var tech=(document.querySelector("input[name='spw_tech']:checked")||{}).value||"";
    var svgColor=(document.querySelector("input[name='spw_svg_color']:checked")||{}).value||"";
    var notes=($val("spw_notes","")||"").trim();
    if(!variantId){ alert("Falta la variante del producto."); return; }

    var du=null,pngB64="";
    try{
      du=await renderPNGDataURL();
      sessionStorage.setItem('spw_last_product_id', String(variantId));
      sessionStorage.setItem('spw_last_png', du||'');
      sessionStorage.setItem('spw_last_color', svgColor||'');
      pngB64=du?du.split('base64,')[1]:"";
    }catch(_){}

    var r1=await postJSON("/spw/add_to_cart_meta",{variant_id:parseInt(variantId,10),qty:qty,tech:tech,svg_color:svgColor,notes:notes});
    if(!r1.ok){ r1=await postForm("/spw/add_to_cart_meta_http",{variant_id:variantId,qty:qty,tech:tech,svg_color:svgColor,notes:notes}); }
    if(!r1.ok){ alert((r1.data&&r1.data.message)?r1.data.message:"No se pudo añadir al carrito."); return; }

    try{ if(r1.data && r1.data.line_id) sessionStorage.setItem('spw_last_line_id', String(r1.data.line_id)); }catch(_){}

    if(pngB64){
      var r2=await postJSON("/spw/attach_png",{line_id:r1.data.line_id,png_b64:pngB64});
      if(!r2.ok){ await postForm("/spw/attach_png_http",{line_id:r1.data.line_id,png_b64:pngB64}); }
    }

    var baseUrl=(r1.data&&r1.data.cart_url)||"/shop/cart";
    var withParam=(r1.data&&r1.data.line_id)?(baseUrl+(baseUrl.indexOf('?')===-1?'?':'&')+'spw_line_id='+encodeURIComponent(r1.data.line_id)):baseUrl;
    window.location.href=withParam;
  }

  async function downloadPNGiOSSafe(){
    try{
      var dataUrl=await renderPNGDataURL();
      var a=document.createElement("a"); a.href=dataUrl; a.download="personalizacion.png";
      if(typeof a.download==="undefined"){ window.location.href=dataUrl; }
      else{ document.body.appendChild(a); a.click(); a.remove(); }
    }catch(_){ alert("No se pudo generar el PNG."); }
  }

  function init(){
    var file=$("#spw_logo_input"), logo=$("#spw_logo_preview");
    if(file){ file.addEventListener("change", async function(e){ var f=e.target.files && e.target.files[0]; if(!f) return; var url=await readAsDataURL(f); logo.src=url; applyTransform(); });}
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(id=>{ var el=$("#"+id); if(el) el.addEventListener("input", applyTransform); });
    window.spwReset=function(){ $("#spw_size").value=100; $("#spw_pos_x").value=0; $("#spw_pos_y").value=10; $("#spw_rotation").value=0; applyTransform(); };
    var dl=$("#spw_download_png"); if(dl) dl.addEventListener("click", downloadPNGiOSSafe);
    var add=$("#spw_add_to_cart"); if(add) add.addEventListener("click", addToCart);
    applyTransform();
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
(function(){
  "use strict";
  function q(s,r){return (r||document).querySelector(s);}
  function qa(s,r){return Array.from((r||document).querySelectorAll(s));}

  function getUrlParam(name){ try{ return new URL(location.href).searchParams.get(name); }catch(_){ return null; } }
  function parseLineIdFromHref(node){
    try{
      var a=(node.closest && node.closest('a[href*="line_id="]')) || (node.querySelector && node.querySelector('a[href*="line_id="]'));
      if(!a) return null; var u=new URL(a.getAttribute('href'), location.origin); return u.searchParams.get('line_id');
    }catch(_){ return null; }
  }
  function getLineId(line){
    if(!line) return null;
    return line.getAttribute('data-line-id')
        || (q('input[name="line_id"]', line)||{}).value
        || parseLineIdFromHref(line)
        || null;
  }
  function findLines(){
    var sel=".js_cart_lines .row, .o_wsale_cart_item, tr.js_cart_line, [data-line-id], .card.js_cart_item, .o_cart_line";
    return qa(sel);
  }
  function holderFor(line){
    return q(".o_wsale_cart_quantity", line)
        || q("div[name='quantity']", line)
        || q(".css_quantity", line)
        || q(".input-group-append", line)
        || q(".input-group", line)
        || line;
  }
  function findMetaContainer(line){
    var elems=qa('p,div,li,span', line);
    var meta=elems.find(function(el){
      var t=(el.textContent||"").toLowerCase();
      return /t[eé]cnica/.test(t) || /color svg/.test(t) || /color\s*#/.test(t);
    });
    return meta; // puede ser null
  }
  function extractHexFromText(text){
    var m=(text||"").match(/#([0-9a-fA-F]{6})\b/);
    return m?('#'+m[1]):null;
  }

  function cleanupOrphans(lines){
    qa(".spw-preview").forEach(function(p){
      // solo borramos si NO está dentro de NINGUNA línea detectada
      var keep = lines.some(function(ln){ return ln.contains(p); });
      if(!keep) p.remove();
    });
  }

  function insertPreview(line, src, lineId, hex){
    // borra duplicados en esta línea
    qa(".spw-preview", line).forEach(function(n){ n.remove(); });

    // objetivo de inserción: prioridad meta dentro de la línea; si meta no pertenece a la línea, usamos holder; si no, la propia línea
    var meta=findMetaContainer(line);
    var target = (meta && line.contains(meta)) ? meta : holderFor(line);

    var wrap=document.createElement("div");
    wrap.className="spw-preview";
    if(lineId) wrap.setAttribute("data-line", lineId);

    var img=new Image();
    img.alt="Personalización"; img.loading="lazy"; img.src=src;
    img.onerror=function(){ wrap.remove(); };
    wrap.appendChild(img);

    var colorToShow = extractHexFromText((meta && meta.textContent) || line.textContent || "") || hex;
    if(colorToShow && /^#[0-9A-F]{6}$/i.test(colorToShow)){
      var sw=document.createElement("span");
      sw.className="spw-swatch"; sw.title=colorToShow; sw.style.background=colorToShow;
      wrap.appendChild(sw);
    }

    // si target es meta: ponemos debajo; si es holder/line: al final
    if(meta && line.contains(meta) && target===meta){
      target.insertAdjacentElement("afterend", wrap);
    }else{
      target.appendChild(wrap);
    }
  }

  var rafId=null; function schedule(fn){ if(rafId) cancelAnimationFrame(rafId); rafId=requestAnimationFrame(fn); }

  function inject(){
    if(!/\/shop\/cart/.test(location.pathname)) return;

    var wanted=getUrlParam('spw_line_id');
    var lastId=null,lastPng=null,lastColor=null;
    try{
      lastId=sessionStorage.getItem('spw_last_line_id');
      lastPng=sessionStorage.getItem('spw_last_png');
      lastColor=sessionStorage.getItem('spw_last_color');
    }catch(_){}

    var lines=findLines();
    if(!lines.length) return;

    cleanupOrphans(lines);

    lines.forEach(function(line){
      var id=getLineId(line);
      if(!id) return;

      if(wanted && lastId && id===lastId && lastPng){
        insertPreview(line, lastPng, id, lastColor);
        return;
      }
      var url="/spw/line_preview/"+encodeURIComponent(id)+".png?_="+Date.now();
      insertPreview(line, url, id, null);
    });

    if(wanted && lastId && wanted===lastId){
      try{
        sessionStorage.removeItem('spw_last_line_id');
        sessionStorage.removeItem('spw_last_png');
        sessionStorage.removeItem('spw_last_color');
      }catch(_){}
    }
  }

  function boot(){
    var root=document.body;
    if(window.MutationObserver && root){
      var mo=new MutationObserver(function(){ schedule(inject); });
      mo.observe(root,{childList:true,subtree:true});
    }
    setTimeout(inject,120);
    setTimeout(inject,360);
    setTimeout(inject,900);
    setTimeout(inject,1800);
    window.addEventListener('pageshow', inject);
    window.addEventListener('popstate', inject);
    window.addEventListener('hashchange', inject);
    inject();
  }

  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", boot); } else { boot(); }
})();
